$ErrorActionPreference='Stop'
$repo=Split-Path (Split-Path (Split-Path $PSScriptRoot -Parent) -Parent) -Parent
$catalog=Get-Content "$repo/src/Rules/requirements/magebean-catalog.json" -Raw|ConvertFrom-Json
$backlog=Get-Content "$repo/src/Rules/requirements/magebean-automation-backlog.json" -Raw|ConvertFrom-Json
$profiles=Get-Content "$repo/src/Rules/requirements/internal-profiles.json" -Raw|ConvertFrom-Json
$review=Get-Content "$PSScriptRoot/review.json" -Raw|ConvertFrom-Json
$source=Get-Content "$PSScriptRoot/source-implementation.json" -Raw|ConvertFrom-Json
$runtime=Get-Content "$PSScriptRoot/runtime-implementation.json" -Raw|ConvertFrom-Json
$dependency=Get-Content "$PSScriptRoot/dependencies-implementation.json" -Raw|ConvertFrom-Json
$runtimeMap=@{'MB-0799'='MB-0004';'MB-0800'='MB-0748';'MB-0801'='MB-0101';'MB-0802'='MB-0089';'MB-0803'='MB-0096';'MB-0804'='MB-0745';'MB-0805'='MB-0064';'MB-0806'='MB-0053';'MB-0807'='MB-0738'}
if (@($catalog.requirements|Where-Object id -eq 'MB-0807').Count -ne 1) { throw 'Runtime catalog integration must finish before manifest generation.' }
$reuseOnly=@('MB-0731','MB-0739','MB-0740','MB-0741','MB-0742','MB-0744','MB-0097')
$rows=@(foreach($old in $backlog.requirements) {
 $r=$review.requirements|Where-Object id -eq $old.id
 $s=$source|Where-Object backlog_id -eq $old.id
 $p=$runtime|Where-Object id -eq $old.id
 $d=$dependency.rows|Where-Object id -eq $old.id
 $new=@($catalog.requirements|Where-Object { ($_.automation_backlog_ids -contains $old.id) -or ($runtimeMap[$_.id] -eq $old.id) })
 $related=@($r.covered_by_active_ids)+@($p.reuse_active_ids)+@($d.reuse_active_ids)
 if($old.id -eq 'MB-0097'){$related+=@('MB-0730')}
 $related=@($related|Where-Object {$_ -and $_ -notin @($new.id)}|Sort-Object -Unique)
 $reason=if($s){$s.why}elseif($d){$d.reason}elseif($p){@($p.limitations)-join ' '}else{$r.rationale}
 $disposition=if($new.Count){'NEW_SCOPED_CHECK'}elseif($old.id -eq 'MB-0077'){'SIGNAL_ONLY'}elseif($r.verdict -eq 'NOT_AUTOMATABLE'){'OUT_OF_SCOPE'}elseif($old.id -in $reuseOnly){'REUSE_ACTIVE_SUBSET'}else{'ADAPTER_PENDING'}
 [pscustomobject][ordered]@{backlog_id=$old.id;original_title=$old.title;original_criterion=$old.criterion;feasibility_verdict=$r.verdict;disposition=$disposition;new_scoped_ids=@($new.id);related_active_ids=$related;original_requirement_reactivated=$false;full_original_criterion_claimed=$false;reason=$reason;new_checks=@($new|ForEach-Object {$newDefinition=$_; [ordered]@{id=$newDefinition.id;title=$newDefinition.title;criterion=$newDefinition.criterion;checks=$newDefinition.checks;capability=$newDefinition.applicability.capability;profiles=@($profiles.profiles.psobject.Properties|Where-Object {$_.Value.requirement_ids -contains $newDefinition.id}|ForEach-Object Name)}})}
})
if($rows.Count -ne 50 -or @($rows.backlog_id|Sort-Object -Unique).Count -ne 50){throw 'Expected exactly 50 distinct original backlog dispositions.'}
$newIds=@($rows.new_scoped_ids|Sort-Object -Unique)
$counts=[ordered]@{};foreach($group in ($rows|Group-Object disposition)){$counts[$group.Name]=$group.Count}
$tests=@('AutomatedSourcePolicyTest.php','DependencyPolicyCheckTest.php','ProductionRuntimeCheckTest.php','ProductionCheckPolicyTest.php','LinuxWorkerObservationTest.php','AutomationBacklogRegistrySmokeTest.php','AutomationBacklogCollectionRegressionTest.php','HardeningCoverageTest.php')
$manifest=[pscustomobject][ordered]@{date='2026-10-18';scope='All 50 historical Magebean automation backlog requirements; actual implementation dispositions, not 47 completed requirements';counts=$counts;new_distinct_scoped_requirements=$newIds.Count;new_scoped_ids=$newIds;original_requirements_reactivated=0;human_workflow_added=0;profile_counts=[ordered]@{basic=$profiles.profiles.basic.requirement_ids.Count;hardening=$profiles.profiles.hardening.requirement_ids.Count;owasp=$profiles.profiles.'owasp-top-10-2025'.requirement_ids.Count};validation=[ordered]@{tests=$tests;collection_regression='12 assertions passed, including shared active cache/reset, global deadline and empty worker maps';note='Use final root test run for complete suite status; named tests are relevant coverage, not a claim all adapters are implemented.'};remaining_adapters=@('Complete Magento route/role/ownership integration fixtures and protected-byte/side-effect oracles','Provider-specific webhook HMAC/replay contracts and installed version mapping','Context-aware HTML/JavaScript escaping and serializer semantics','Effective secret-storage provenance across Magento config, database and actual secret stores','Complete enabled-module/package and Marketplace/vendor support lifecycle/entitlement providers','Dated complete KEV membership and CVE alias coverage contract','Bound complete runtime logging architecture and retention/rotation adapters','Namespace-aware effective firewall/CNI/gateway policy and complete cipher enumeration','Actual integration ACL and network policy adapter with explicit integration inventory');requirements=$rows}
$manifest|ConvertTo-Json -Depth 30|Set-Content "$PSScriptRoot/implementation.json" -Encoding utf8
$lines=@('# Magebean automation backlog implementation','','This report maps all 50 historical backlog items to actual implementation. It does not claim that all 47 feasibility candidates were implemented or that production is fully protected. Original IDs and criteria stay preserved; new predicates use scoped identities.','','| Disposition | Original backlog items |','|---|---:|')
foreach($key in $counts.Keys){$lines+="| $key | $($counts[$key]) |"}
$lines+=@('',"There are **$($newIds.Count) distinct new scoped requirement IDs**. Multiple old items may share one new syntax predicate; those are counted once. Basic has $($manifest.profile_counts.basic), Hardening $($manifest.profile_counts.hardening), and Magebean OWASP $($manifest.profile_counts.owasp) catalog requirements. Actual selected checks depend on target mode and declared capabilities.",'','Strict native API bans require the `strict_native_api_policy` capability in the profile planner. These bans intentionally include benign uses and must be adopted as technical coding policy. Registry direct calls execute the requested predicate; they do not perform profile capability selection. Omissions and collection errors must remain visible, not implicit PASS.','','Machine policy inputs are expected-state configuration. They do not contain statements that protection exists, reviewer approval or human evidence. Missing, malformed, stale or incomplete required inputs remain UNKNOWN.','','```json','{"schema_version":1,"checks":{"production_direct_global_roles_approved":{"approved_role_ids":[2]},"production_integration_debug_defaults_disabled":{"paths":["example_vendor/debug/enabled"]},"dependency_mitigation_records":{"expected_ids":["temporary-1"]}}}','```','','Place this in `.magebean/production-checks.json` only after replacing role IDs and vendor paths with the intended installed deployment policy. The example vendor path is illustrative, not a verified universal Magento integration setting. Worker readonly checks additionally require actual PHP-FPM worker PIDs and matching unprivileged scanner identity. Linux Xdebug checks require `.magebean/php-fpm-workers.json` with pool, PID and current process start_ticks. Invented or expired identities cannot pass.','','Dependency source policy `.magebean/dependency-source-policy.json` uses `schema_version:1`, exact `root_repositories`, and a `packages` object keyed by package name. Each package must supply exact source/dist URL and nonempty reference plus expected replace declarations; explicit metadata-only metapackages are special. Both source and dist declarations are checked where present. This does not verify installed bytes or assert approved source is benign.','','Mitigation `.magebean/mitigations.json` uses `schema_version:1`, current RFC3339 `generated_at`, and `records` with id, advisory, package, version, owner, action, rollback and future expires_at. The predicate validates declared record structure, freshness, expiry and nonempty configured expected IDs only. It cannot prove a mitigation is deployed, effective or comprehensively inventoried.','','New finding guidance must describe exact observed syntax/config/runtime scope, safe remediation and rerun verification. Do not replace framework APIs solely to make a finding disappear; preserve validation, parameter binding, authorization, output-context handling and intended business behavior. Do not remove mandatory security logging to satisfy a debug policy. No payload contents, credentials, PHP process environ or memory addresses should be reported.','','| Historical ID | Disposition | New scoped IDs | Related active IDs |','|---|---|---|---|')
foreach($row in $rows){$lines+="| $($row.backlog_id) | $($row.disposition) | $($row.new_scoped_ids -join ', ') | $($row.related_active_ids -join ', ') |"}
$lines+=@('','Opt-in capabilities in the actual catalog:','','| Capability | Scoped IDs |','|---|---|')
foreach($group in (@($rows.new_checks|Where-Object capability)|Group-Object { $_.capability })) {$lines+="| $($group.Name) | $(@($group.Group.id|Sort-Object -Unique) -join ', ') |"}
$lines+=@('','Declare intended capabilities through `--capabilities=NAME,NAME` when listing/scanning. Enabling a capability selects the predicate; it does not fabricate required policy files or runtime observations. For example `--profile=hardening --capabilities=dependency_source_policy` still needs the complete project-local source policy and lock metadata. Default scans report omitted capability-bound IDs; they do not claim those predicates passed.','','Remaining adapters:');foreach($adapter in $manifest.remaining_adapters){$lines+="- $adapter"}
$lines+=@('','Relevant regression tests:');foreach($test in $tests){$lines+="- tests/$test"}
$lines+=@('','No production scan, production import or PHAR rebuild is implied by this report. Existing assessment snapshots retain their historical definitions; imported catalog changes require a fresh/updated assessment and new collected evidence.')
$lines|Set-Content "$PSScriptRoot/implementation.md" -Encoding utf8
Write-Output ($manifest|Select-Object counts,new_distinct_scoped_requirements,profile_counts|ConvertTo-Json -Depth 5)


